type KnowledgeServiceHTTPClient interface {
	// CreateCollection Collections
	CreateCollection(ctx context.Context, req *CreateCollectionRequest, opts ...http.CallOption) (rsp *KnowledgeCollection, err error)
	// CreateVaultDir CreateVaultDir creates a directory inside the vault (G1-B2; idempotent).
	CreateVaultDir(ctx context.Context, req *CreateVaultDirRequest, opts ...http.CallOption) (rsp *emptypb.Empty, err error)
	// CreateVaultDocument CreateVaultDocument writes a template .md (frontmatter + empty heading) and
	// indexes it immediately (G1-B2; no 45s poll wait). Existing path = conflict.
	CreateVaultDocument(ctx context.Context, req *CreateVaultDocumentRequest, opts ...http.CallOption) (rsp *KnowledgeDocument, err error)
	DeleteCollection(ctx context.Context, req *DeleteCollectionRequest, opts ...http.CallOption) (rsp *emptypb.Empty, err error)
	DeleteDocument(ctx context.Context, req *DeleteDocumentRequest, opts ...http.CallOption) (rsp *emptypb.Empty, err error)
	// EnableCollectionSemantic EnableCollectionSemantic one-way enables the semantic layer on a lexical-only
	// collection (B2): binds the current global embedder model/dim (guarded UPDATE,
	// conflict when already enabled) and enqueues all content documents into the
	// B1 re-embed pipeline. CodeBadRequest when the embedder is not configured.
	EnableCollectionSemantic(ctx context.Context, req *EnableCollectionSemanticRequest, opts ...http.CallOption) (rsp *EnableCollectionSemanticResponse, err error)
	GetCollection(ctx context.Context, req *GetCollectionRequest, opts ...http.CallOption) (rsp *KnowledgeCollection, err error)
	GetDocumentContent(ctx context.Context, req *GetDocumentContentRequest, opts ...http.CallOption) (rsp *DocumentContent, err error)
	GetEmbedderConfig(ctx context.Context, req *GetEmbedderConfigRequest, opts ...http.CallOption) (rsp *EmbedderConfig, err error)
	// IngestDocument Documents
	IngestDocument(ctx context.Context, req *IngestDocumentRequest, opts ...http.CallOption) (rsp *KnowledgeDocument, err error)
	// ListBlockBacklinks ListBlockBacklinks returns block-level inbound references (SP1-E): context
	// excerpt + source block/document per edge. Single block via block_id path;
	// aggregate all blocks of a document via the doc_id binding.
	ListBlockBacklinks(ctx context.Context, req *ListBlockBacklinksRequest, opts ...http.CallOption) (rsp *ListBlockBacklinksResponse, err error)
	// ListCollectionGraph ListCollectionGraph returns the full link graph of one collection (G4-B8):
	// nodes = documents (after path_prefix filter), edges = links (link_types filter;
	// endpoints outside scope/dangling dropped), degree = in-edge count per node.
	ListCollectionGraph(ctx context.Context, req *ListCollectionGraphRequest, opts ...http.CallOption) (rsp *ListCollectionGraphResponse, err error)
	ListCollections(ctx context.Context, req *ListCollectionsRequest, opts ...http.CallOption) (rsp *ListCollectionsResponse, err error)
	// ListDanglingLinks ListDanglingLinks aggregates dangling references of one collection by
	// raw_target with ref counts (SP1-E; "uncreated notes" view).
	ListDanglingLinks(ctx context.Context, req *ListDanglingLinksRequest, opts ...http.CallOption) (rsp *ListDanglingLinksResponse, err error)
	// ListDocumentLinks Document relations with source-type annotation (P3 关联区, R-3).
	ListDocumentLinks(ctx context.Context, req *ListDocumentLinksRequest, opts ...http.CallOption) (rsp *ListDocumentLinksResponse, err error)
	// ListDocumentNeighborhood ListDocumentNeighborhood returns the N-hop undirected neighborhood subgraph
	// of one document (SP2-8 右栏局部图): same node/edge shape as the full graph,
	// but only the small vicinity is transferred (large-vault friendly).
	ListDocumentNeighborhood(ctx context.Context, req *ListDocumentNeighborhoodRequest, opts ...http.CallOption) (rsp *ListCollectionGraphResponse, err error)
	ListDocuments(ctx context.Context, req *ListDocumentsRequest, opts ...http.CallOption) (rsp *ListDocumentsResponse, err error)
	// ListEntityMergeSuggestions ListEntityMergeSuggestions lists entity merge candidates (G5-F B11):
	// normalization conflict groups (same name_norm, different display name)
	// plus high-similarity embedding pairs when the embedder is configured.
	// Computed in real time; no queue table.
	ListEntityMergeSuggestions(ctx context.Context, req *ListEntityMergeSuggestionsRequest, opts ...http.CallOption) (rsp *ListEntityMergeSuggestionsResponse, err error)
	// ListGovernanceProposals ListGovernanceProposals lists curation governance proposals (M4 自治理层
	// 人工二审出口): high-risk conflict/orphan proposals wait here for human review.
	ListGovernanceProposals(ctx context.Context, req *ListGovernanceProposalsRequest, opts ...http.CallOption) (rsp *ListGovernanceProposalsResponse, err error)
	// ListRecentLinkUses ListRecentLinkUses returns recently used wikilink targets of one
	// collection, most recent first (B4 #8); drives empty-query [[ completion
	// ordering on the client.
	ListRecentLinkUses(ctx context.Context, req *ListRecentLinkUsesRequest, opts ...http.CallOption) (rsp *ListRecentLinkUsesResponse, err error)
	// ListUnlinkedMentions ListUnlinkedMentions returns documents that mention the target doc's name
	// in plain text (outside [[wikilinks]]) without linking to it (P2-7).
	ListUnlinkedMentions(ctx context.Context, req *ListUnlinkedMentionsRequest, opts ...http.CallOption) (rsp *ListUnlinkedMentionsResponse, err error)
	// ListVaultTree Vault explorer (P3): lazy folder listing derived from document rel_paths.
	ListVaultTree(ctx context.Context, req *ListVaultTreeRequest, opts ...http.CallOption) (rsp *ListVaultTreeResponse, err error)
	// MergeKnowledgeEntities MergeKnowledgeEntities merges mergee entities into the keeper (G5-F B10)
	// atomically; returns rewrite counts for inline UI feedback.
	MergeKnowledgeEntities(ctx context.Context, req *MergeKnowledgeEntitiesRequest, opts ...http.CallOption) (rsp *MergeKnowledgeEntitiesResponse, err error)
	MoveDocument(ctx context.Context, req *MoveDocumentRequest, opts ...http.CallOption) (rsp *KnowledgeDocument, err error)
	// MoveDocumentToDir MoveDocumentToDir moves a vault document to another directory within the same
	// collection (G3-B4): atomic fs move + rel_path update (identity/chunks kept) +
	// inbound explicit links rebuild. Name clash -> CodeConflict unless
	// conflict_policy=overwrite|rename. Vault documents only (rel_path required).
	MoveDocumentToDir(ctx context.Context, req *MoveDocumentToDirRequest, opts ...http.CallOption) (rsp *KnowledgeDocument, err error)
	// PromoteBlocks PromoteBlocks clones blocks from a personal vault into a team collection
	// (SP1-G, US-27): copy-not-move with lineage pair (promoted_from/promoted_to),
	// cascade candidates for references into private blocks, and immediate
	// re-indexing of the target document so promoted content is searchable.
	PromoteBlocks(ctx context.Context, req *PromoteBlocksRequest, opts ...http.CallOption) (rsp *PromoteBlocksResponse, err error)
	// RebuildKnowledgeIndex RebuildKnowledgeIndex rebuilds the block-level derived index (blocks/refs)
	// for every document of the collection (SP1-H, US-29). Asynchronous and
	// idempotent; 409 Conflict while a rebuild is already running for the same
	// collection. Progress via knowledge WS events (EP-KN-02 pattern); chunks/FTS
	// stay on old data during the rebuild (degraded but available).
	RebuildKnowledgeIndex(ctx context.Context, req *RebuildKnowledgeIndexRequest, opts ...http.CallOption) (rsp *RebuildKnowledgeIndexResponse, err error)
	// RecordLinkUse RecordLinkUse upserts the (collection, doc) recency row when a wikilink
	// completion is applied (B4 #8); best-effort, callers may ignore failures.
	RecordLinkUse(ctx context.Context, req *RecordLinkUseRequest, opts ...http.CallOption) (rsp *RecordLinkUseResponse, err error)
	// ReembedDocuments ReembedDocuments re-chunks and re-embeds documents from their stored
	// content_text (B1: heals UI-uploaded docs whose embeddings were nulled by
	// reconcileEmbeddingDim; vault docs self-heal via vault_sync and are skipped).
	ReembedDocuments(ctx context.Context, req *ReembedDocumentsRequest, opts ...http.CallOption) (rsp *ReembedDocumentsResponse, err error)
	// ResolveGovernanceProposal ResolveGovernanceProposal closes one pending proposal (人工二审):
	// decision=applied approves the governance action, rejected dismisses it.
	ResolveGovernanceProposal(ctx context.Context, req *ResolveGovernanceProposalRequest, opts ...http.CallOption) (rsp *ResolveGovernanceProposalResponse, err error)
	// Search Search
	Search(ctx context.Context, req *SearchRequest, opts ...http.CallOption) (rsp *SearchResponse, err error)
	// UpdateDocumentContent UpdateDocumentContent saves editor body back to the vault file (G2-B5):
	// frontmatter preserved, CAS via base_hash; conflict still writes (disk copy
	// backed up to trash) and returns conflict=true. Triggers immediate reindex.
	UpdateDocumentContent(ctx context.Context, req *UpdateDocumentContentRequest, opts ...http.CallOption) (rsp *UpdateDocumentContentResponse, err error)
	UpdateEmbedderConfig(ctx context.Context, req *UpdateEmbedderConfigRequest, opts ...http.CallOption) (rsp *UpdateEmbedderConfigResponse, err error)
}

